# owner: platform
"""Seating charts: students by last name, in rows."""

from typing import Iterable, List
from rosterkit.models import Student
from operator import attrgetter


# ---
def seating_rows(
    students: Iterable[Student], per_row: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    roster = list(students)
    _check_seating(roster, per_row)
    ordered = sorted(roster, key=attrgetter("last_name"))
    return _format_rows(_chunk_students(ordered, per_row))


def _check_seating(
    roster: List[Student], per_row: int
) -> None:
    if per_row <= 0:
        raise ValueError(f"bad seat count {per_row}")
    if not roster:
        raise ValueError("no students to seat")


def _chunk_students(
    ordered: List[Student], per_row: int
) -> List[List[Student]]:
    """Split the sorted class into rows of per_row each."""
    starts = range(0, len(ordered), per_row)
    return [
        ordered[start:start + per_row] for start in starts
    ]


def _format_rows(groups: List[List[Student]]) -> List[str]:
    rows = enumerate(groups, start=1)
    return [
        _format_row(number, group) for number, group in rows
    ]


def _format_row(number: int, group: List[Student]) -> str:
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"

