# owner: platform
"""Tests for seating charts."""

import unittest
from rosterkit.seating import seating_rows
from rosterkit.models import Student


# ---
def make_student(
    last_name: str, first_name: str
) -> Student:
    return Student("1", last_name, first_name, "A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.roster = [
            make_student("Quill", "Ines"),
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet")
        ]

    def test_rows_sorted_by_last_name(self):
        expected = [
            "Row 1: Dunmere, Piet | Halloway, Juno",
            "Row 2: Quill, Ines"
        ]
        rows = seating_rows(self.roster, 2)
        self.assertEqual(rows, expected)

    def test_one_row_when_seats_exceed_class(self):
        rows = seating_rows(self.roster, 10)
        self.assertEqual(len(rows), 1)

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.roster, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.roster, -3)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
